################################################################################
# Reproducibility check
################################################################################
# This script compares the audit results generated by the authors
# by running 05_audit_workflow.R on MacOS or on Windows,
# with the corresponding results reported in folders 
# - ./simstudy/sim_results_A/audit/audit_by_authors/unix
# - ./simstudy/sim_results_A/audit/audit_by_authors/windows
################################################################################

# Session -> Set Working Directory -> To Source File Location
#setwd('/home/spreaficom/jmdf/simstudy')
setwd(file.path(getwd(),'simstudy'))

################################################################################
# Function audit.checks.jmdf.unix.wind()
################################################################################
# Compare audit results provided by authors generated via "05_audit_workflow.R"
# using MacOS or Windows. This is a modified version of audit.checks.jmdf() 
# in "06_audit_reproducibility_checks.R"
audit.checks.jmdf.unix.wind <- function(setting, folder, method, tol = 1e-8) {
  
  # Check that method is valid
  if (!method %in% c("gauss", "unif")) {
    stop("method must be either 'gauss' or 'unif'")
  }
  
  audit.checks <- do.call(
    rbind,
    # Loop over the nine simulation scenarios
    lapply(1:9, function(scenario) {
      
      # Load audit results from windows
      audit.windows = paste0("sim_results_",setting,"/audit/audit_by_authors/windows/s",
                             scenario,"_JMDF_",method, folder,".Rdata")
      if (!file.exists(audit.windows)) {
        stop("Audit results not found. Please run '05_audit_workflow.R' first.")
      }
      load(audit.windows)
      coef.results.windows <- coef.results
      frail.results.windows <- frail.results
      
      
      # Load audit results from macOS
      audit.unix = paste0("sim_results_",setting,"/audit/audit_by_authors/unix/s",
                          scenario,"_JMDF_",method, folder,".Rdata")
      load(audit.unix)
      coef.results.unix <- coef.results
      frail.results.unix <- frail.results
      
      # Compare the Windows and unix/macOS replications
      audit.reps = nrow(coef.results.windows)
      # Model estimates and standard errors to be compared
      coef.vars = c("beta1", "beta2","gamma1", "gamma2",
                    "se_beta1", "se_beta2","se_gamma1", "se_gamma2")
      
      data.frame(
        scenario = scenario,
        replication = 1:audit.reps,
        
        # Compare coefficient estimates and SEs
        # excluding K, AIC, n.iter from the comparison
        coef.results = sapply(
          1:audit.reps,
          function(i)
            isTRUE(all.equal(
              coef.results.windows[i, coef.vars, drop = FALSE],
              coef.results.unix[i, coef.vars, drop = FALSE],
              tolerance = tol
            ))
        ),
        
        # Compare the number of frailty groups
        K = sapply(
          1:audit.reps,
          function(i) {
            coef.results.windows$K[i] ==
              coef.results.unix$K[i]
          }
        ),
        
        # Report the difference in the number of frailty groups
        K_difference = sapply(
          1:audit.reps,
          function(i) {
            coef.results.windows$K[i] -
              coef.results.unix$K[i]
          }
        ),
        
        # Compare frailty estimates only when K is the same
        frail.results = sapply(
          1:audit.reps,
          function(i) {
            
            K.windows <- coef.results.windows$K[i]
            K.unix <- coef.results.unix$K[i]
            
            if (K.windows != K.unix) {
              return("Not comparable")
            }
            
            # Fix label switching
            windows_i <- frail.results.windows[frail.results.windows$rep_b == i, , drop = FALSE]
            unix_i <- frail.results.unix[frail.results.unix$rep_b == i, , drop = FALSE]
            
            # Order groups by Pu
            windows_i <- windows_i[order(windows_i$Pu), , drop = FALSE]
            unix_i <- unix_i[order(unix_i$Pu), , drop = FALSE]
            
            # Remove group labels and rownames because they are arbitrary
            windows_i$group <- NULL
            unix_i$group <- NULL
            
            rownames(windows_i) <- NULL
            rownames(unix_i) <- NULL
            
            isTRUE(all.equal(windows_i, unix_i, tolerance = tol))
          }
        )
      )
    })
  )
  
  return(audit.checks)
}


################################################################################
# JMDF audit results comparisons
################################################################################

# We can evaluate reproducibility using different numerical tolerances.
# Strict tolerances assess near-exact numerical agreement, whereas larger
# tolerances assess whether the results agree within a small numerical
# difference.
#
# The number of frailty groups (K) is checked separately and exactly, since
# a difference in K represents a difference in the selected support rather
# than a simple numerical discrepancy. The K_difference column reports the
# difference between the number of groups obtained in the audit and in the
# corresponding full-workflow result: a value of 0 indicates identical K,
# whereas a negative or positive value indicates fewer or more groups,
# respectively, in the audit result.


# JMDF Gaussian initialization (ii) with L = 1.5
#----------------------------------------------------------------------
# Strict tolerance
rep_checks_gauss = audit.checks.jmdf.unix.wind(setting = "A", folder = "II_L15",
                                               method = "gauss", tol=1e-8)
print(rep_checks_gauss)


# JMDF Uniform initialization (ii) with L = 1.5
#----------------------------------------------------------------------
# Strict tolerance
rep_checks_unif = audit.checks.jmdf.unix.wind(setting = "A", folder = "II_L15",
                                              method = "unif", tol=1e-8)
print(rep_checks_unif)

# Large tolerance
rep_checks_unif = audit.checks.jmdf.unix.wind(setting = "A", folder = "II_L15",
                                              method = "unif", tol=1e-2)
print(rep_checks_unif)



